// Administrable.test.js: Administrable - Basic Admin Management Tests > 👤 Basic Admin Management > Role Changes > Should prevent changing to NONE role
const { expect } = require("chai");
const { ethers } = require("hardhat");
let administrable;
let owner, admin1, admin2, nonAdmin, newAdmin;
const AdminRole = {
    NONE: 0,
    TEAM_MANAGER: 1,
    VOTE_ADMIN: 2,
    RECOVERY_ADMIN: 3,
    SUPER_ADMIN: 4,
  };
// beforeEach of suite "Administrable - Basic Admin Management Tests"
beforeEach(async function () {
    [owner, admin1, admin2, nonAdmin, newAdmin] = await ethers.getSigners();

    // Deploy simplified Administrable contract
    const Administrable = await ethers.getContractFactory("Administrable");
